    10→use crate::core::Camera;
    11→use byteorder::{LittleEndian, ReadBytesExt};
    12→use nalgebra::{Matrix3, UnitQuaternion, Vector3};
    13→use std::collections::HashMap;
    14→use std::fs::File;
    15→use std::io::BufReader;
    16→use std::path::Path;
    17→use thiserror::Error;
    18→
    19→/// Errors that can occur when loading COLMAP data.
    20→#[derive(Debug, Error)]
    21→pub enum LoadError {
    22→    #[error("I/O error: {0}")]
    23→    Io(#[from] std::io::Error),
    24→
    25→    #[error("Invalid COLMAP binary format: {0}")]
    26→    InvalidFormat(String),
    27→
    28→    #[error("Unsupported camera model: {0}")]
    29→    UnsupportedCameraModel(i32),
    30→}
    31→
    32→/// A complete COLMAP scene with cameras, images, and 3D points.
    33→#[derive(Debug, Clone)]
    34→pub struct ColmapScene {
    35→    /// Camera parameters (intrinsics), indexed by camera_id
    36→    pub cameras: HashMap<u32, Camera>,
    37→
    38→    /// Image metadata (file paths, camera poses)
    39→    pub images: Vec<ImageInfo>,
    40→
    41→    /// 3D points from sparse reconstruction
    42→    pub points: Vec<Point3D>,
    43→}
    44→
    45→/// Information about a single image in the COLMAP reconstruction.
    46→#[derive(Debug, Clone)]
    47→pub struct ImageInfo {
    48→    /// Image ID
    49→    pub id: u32,
    50→
    51→    /// Camera ID (index into cameras array)
    52→    pub camera_id: u32,
    53→
    54→    /// Image file name
    55→    pub name: String,
    56→
    57→    /// Camera pose (rotation + translation to transform world → camera)
    58→    pub rotation: nalgebra::UnitQuaternion<f32>,
    59→    pub translation: Vector3<f32>,
    60→}
    61→
    62→/// A 3D point from COLMAP sparse reconstruction.
    63→#[derive(Debug, Clone)]
    64→pub struct Point3D {
    65→    /// Point ID
    66→    pub id: u64,
    67→
    68→    /// 3D position
    69→    pub position: Vector3<f32>,
    70→
    71→    /// RGB color (0-255)
    72→    pub color: [u8; 3],
    73→
    74→    /// Reprojection error
    75→    pub error: f32,
    76→}
    77→
    78→/// Load a complete COLMAP scene from a directory containing sparse reconstruction.
    79→///
    80→/// Expected directory structure:
    81→/// ```text
    82→/// sparse/0/
    83→///   cameras.bin
    84→///   images.bin
    85→///   points3D.bin
    86→/// ```
    87→pub fn load_colmap_scene(sparse_dir: &Path) -> Result<ColmapScene, LoadError> {
    88→    let cameras_path = sparse_dir.join("cameras.bin");
    89→    let images_path = sparse_dir.join("images.bin");
    90→    let points_path = sparse_dir.join("points3D.bin");
    91→
    92→    // Parse each binary file
    93→    let cameras = read_cameras_bin(&cameras_path)?;
    94→    let images = read_images_bin(&images_path)?;
    95→    let points = read_points3d_bin(&points_path)?;
    96→
    97→    Ok(ColmapScene {
    98→        cameras,
    99→        images,
   100→        points,
   101→    })
   102→}
   103→
   104→/// Read cameras.bin file.
   105→///
   106→/// Binary format (little-endian):
   107→/// - num_cameras: u64
   108→/// - For each camera:
   109→///   - camera_id: u32
   110→///   - model_id: i32 (0=SIMPLE_PINHOLE, 1=PINHOLE, 2=SIMPLE_RADIAL, etc.)
   111→///   - width: u64
   112→///   - height: u64
   113→///   - params: [f64; N] (N depends on model, typically 4 for PINHOLE)
   114→fn read_cameras_bin(path: &Path) -> Result<HashMap<u32, Camera>, LoadError> {
   115→    let file = File::open(path)?;
   116→    let mut reader = BufReader::new(file);
   117→
   118→    let num_cameras = reader.read_u64::<LittleEndian>()?;
   119→    let mut cameras = HashMap::with_capacity(num_cameras as usize);
   120→    let mut has_distortion_models = false; // Track if any cameras have distortion
   121→
   122→    for _ in 0..num_cameras {
   123→        let camera_id = reader.read_u32::<LittleEndian>()?;
   124→        let model_id = reader.read_i32::<LittleEndian>()?;
   125→        let width = reader.read_u64::<LittleEndian>()?;
   126→        let height = reader.read_u64::<LittleEndian>()?;
   127→
   128→        // Parse parameters based on camera model
   129→        // Model IDs: 0=SIMPLE_PINHOLE, 1=PINHOLE, 2=SIMPLE_RADIAL, 3=RADIAL, etc.
   130→        let camera = match model_id {
   131→            0 => {
   132→                // SIMPLE_PINHOLE: f, cx, cy
   133→                let f = reader.read_f64::<LittleEndian>()? as f32;
   134→                let cx = reader.read_f64::<LittleEndian>()? as f32;
   135→                let cy = reader.read_f64::<LittleEndian>()? as f32;
   136→
   137→                Camera::new(
   138→                    f,
   139→                    f, // fx = fy for simple pinhole
   140→                    cx,
   141→                    cy,
   142→                    width as u32,
   143→                    height as u32,
   144→                    Matrix3::identity(), // Will be filled from images.bin
   145→                    Vector3::zeros(),
   146→                )
   147→            }
   148→            1 => {
   149→                // PINHOLE: fx, fy, cx, cy
   150→                let fx = reader.read_f64::<LittleEndian>()? as f32;
   151→                let fy = reader.read_f64::<LittleEndian>()? as f32;
   152→                let cx = reader.read_f64::<LittleEndian>()? as f32;
   153→                let cy = reader.read_f64::<LittleEndian>()? as f32;
   154→
   155→                Camera::new(
   156→                    fx,
   157→                    fy,
   158→                    cx,
   159→                    cy,
   160→                    width as u32,
   161→                    height as u32,
   162→                    Matrix3::identity(),
   163→                    Vector3::zeros(),
   164→                )
   165→            }
   166→            2 | 3 => {
   167→                // SIMPLE_RADIAL / RADIAL: f, cx, cy, k...
   168→                has_distortion_models = true;
   169→                let f = reader.read_f64::<LittleEndian>()? as f32;
   170→                let cx = reader.read_f64::<LittleEndian>()? as f32;
   171→                let cy = reader.read_f64::<LittleEndian>()? as f32;
   172→
   173→                // Skip distortion parameters
   174→                let num_distortion = if model_id == 2 { 1 } else { 2 };
   175→                for _ in 0..num_distortion {
   176→                    reader.read_f64::<LittleEndian>()?;
   177→                }
   178→
   179→                Camera::new(
   180→                    f,
   181→                    f, // fy = fx for radial models
   182→                    cx,
   183→                    cy,
   184→                    width as u32,
   185→                    height as u32,
   186→                    Matrix3::identity(),
   187→                    Vector3::zeros(),
   188→                )
   189→            }
   190→            4 => {
   191→                // OPENCV: fx, fy, cx, cy, k1, k2, p1, p2
   192→                has_distortion_models = true;
   193→                let fx = reader.read_f64::<LittleEndian>()? as f32;
   194→                let fy = reader.read_f64::<LittleEndian>()? as f32;
   195→                let cx = reader.read_f64::<LittleEndian>()? as f32;
   196→                let cy = reader.read_f64::<LittleEndian>()? as f32;
   197→
   198→                // Skip distortion: k1, k2, p1, p2
   199→                for _ in 0..4 {
   200→                    reader.read_f64::<LittleEndian>()?;
   201→                }
   202→
   203→                Camera::new(
   204→                    fx,
   205→                    fy,
   206→                    cx,
   207→                    cy,
   208→                    width as u32,
   209→                    height as u32,
   210→                    Matrix3::identity(),
   211→                    Vector3::zeros(),
   212→                )
   213→            }
   214→            5 => {
   215→                // OPENCV_FISHEYE: fx, fy, cx, cy, k1, k2, k3, k4
   216→                has_distortion_models = true;
   217→                let fx = reader.read_f64::<LittleEndian>()? as f32;
   218→                let fy = reader.read_f64::<LittleEndian>()? as f32;
   219→                let cx = reader.read_f64::<LittleEndian>()? as f32;
   220→                let cy = reader.read_f64::<LittleEndian>()? as f32;
   221→
   222→                // Skip distortion: k1, k2, k3, k4 (4 params, not 12!)
   223→                for _ in 0..4 {
   224→                    reader.read_f64::<LittleEndian>()?;
   225→                }
   226→
   227→                Camera::new(
   228→                    fx,
   229→                    fy,
   230→                    cx,
   231→                    cy,
   232→                    width as u32,
   233→                    height as u32,
   234→                    Matrix3::identity(),
   235→                    Vector3::zeros(),
   236→                )
   237→            }
   238→            _ => return Err(LoadError::UnsupportedCameraModel(model_id)),
   239→        };
   240→
   241→        cameras.insert(camera_id, camera);
   242→    }
   243→
   244→    // Warn if distortion parameters were ignored
   245→    if has_distortion_models {
   246→        eprintln!();
   247→        eprintln!("⚠️  WARNING: COLMAP distortion parameters ignored");
   248→        eprintln!("   Detected non-pinhole camera models (RADIAL, OPENCV, or FISHEYE).");
   249→        eprintln!("   This implementation assumes images are already undistorted.");
   250→        eprintln!();
   251→        eprintln!("   If using raw distorted images, projections will be systematically wrong.");
   252→        eprintln!("   To fix: Use COLMAP's image_undistorter to preprocess your dataset:");
   253→        eprintln!("     colmap image_undistorter \\");
   254→        eprintln!("       --image_path /path/to/images \\");
   255→        eprintln!("       --input_path /path/to/sparse/0 \\");
   256→        eprintln!("       --output_path /path/to/undistorted");
   257→        eprintln!();
   258→    }
   259→
   260→    Ok(cameras)
   261→}
   262→
   263→/// Read images.bin file.
   264→///
   265→/// Binary format (little-endian):
   266→/// - num_images: u64
   267→/// - For each image:
   268→///   - image_id: u32
   269→///   - qw, qx, qy, qz: f64 (rotation quaternion)
   270→///   - tx, ty, tz: f64 (translation)
   271→///   - camera_id: u32
   272→///   - name: null-terminated string
   273→///   - (keypoints data - we can skip for now)
   274→fn read_images_bin(path: &Path) -> Result<Vec<ImageInfo>, LoadError> {
   275→    let file = File::open(path)?;
   276→    let mut reader = BufReader::new(file);
   277→
   278→    let num_images = reader.read_u64::<LittleEndian>()?;
   279→    let mut images = Vec::with_capacity(num_images as usize);
   280→
   281→    for _ in 0..num_images {
   282→        let image_id = reader.read_u32::<LittleEndian>()?;
   283→
   284→        // Read quaternion (qw, qx, qy, qz)
   285→        let qw = reader.read_f64::<LittleEndian>()? as f32;
   286→        let qx = reader.read_f64::<LittleEndian>()? as f32;
   287→        let qy = reader.read_f64::<LittleEndian>()? as f32;
   288→        let qz = reader.read_f64::<LittleEndian>()? as f32;
   289→
   290→        // Read translation (tx, ty, tz)
   291→        let tx = reader.read_f64::<LittleEndian>()? as f32;
   292→        let ty = reader.read_f64::<LittleEndian>()? as f32;
   293→        let tz = reader.read_f64::<LittleEndian>()? as f32;
   294→
   295→        let camera_id = reader.read_u32::<LittleEndian>()?;
   296→
   297→        // Read null-terminated image name
   298→        let mut name_bytes = Vec::new();
   299→        loop {
   300→            let byte = reader.read_u8()?;
   301→            if byte == 0 {
   302→                break;
   303→            }
   304→            name_bytes.push(byte);
   305→        }
   306→        let name = String::from_utf8(name_bytes)
   307→            .map_err(|e| LoadError::InvalidFormat(format!("Invalid UTF-8 in image name: {}", e)))?;
   308→
   309→        // Read 2D points (we skip these for now, but need to read them to advance the file pointer)
   310→        let num_points2d = reader.read_u64::<LittleEndian>()?;
   311→        // Each 2D point is: x (f64), y (f64), point3d_id (u64) = 24 bytes
   312→        for _ in 0..num_points2d {
   313→            reader.read_f64::<LittleEndian>()?; // x
   314→            reader.read_f64::<LittleEndian>()?; // y
   315→            reader.read_u64::<LittleEndian>()?; // point3d_id
   316→        }
   317→
   318→        // Create quaternion (nalgebra uses (w, x, y, z) order internally)
   319→        let rotation =
   320→            UnitQuaternion::from_quaternion(nalgebra::Quaternion::new(qw, qx, qy, qz).normalize());
   321→
   322→        let translation = Vector3::new(tx, ty, tz);
   323→
   324→        images.push(ImageInfo {
   325→            id: image_id,
   326→            camera_id,
   327→            name,
   328→            rotation,
   329→            translation,
   330→        });
   331→    }
   332→
   333→    Ok(images)
   334→}
   335→
   336→/// Read points3D.bin file.
   337→///
   338→/// Binary format (little-endian):
   339→/// - num_points: u64
   340→/// - For each point:
   341→///   - point_id: u64
   342→///   - x, y, z: f64 (position)
   343→///   - r, g, b: u8 (color)
   344→///   - error: f64 (reprojection error)
   345→///   - (track data - we can skip for now)
   346→fn read_points3d_bin(path: &Path) -> Result<Vec<Point3D>, LoadError> {
   347→    let file = File::open(path)?;
   348→    let mut reader = BufReader::new(file);
   349→
   350→    let num_points = reader.read_u64::<LittleEndian>()?;
   351→    let mut points = Vec::with_capacity(num_points as usize);
   352→
   353→    for _ in 0..num_points {
   354→        let point_id = reader.read_u64::<LittleEndian>()?;
   355→
   356→        // Read position (x, y, z)
   357→        let x = reader.read_f64::<LittleEndian>()? as f32;
   358→        let y = reader.read_f64::<LittleEndian>()? as f32;
   359→        let z = reader.read_f64::<LittleEndian>()? as f32;
   360→
   361→        // Read color (r, g, b)
   362→        let r = reader.read_u8()?;
   363→        let g = reader.read_u8()?;
   364→        let b = reader.read_u8()?;
   365→
   366→        // Read error
   367→        let error = reader.read_f64::<LittleEndian>()? as f32;
   368→
   369→        // Read track (list of image observations)
   370→        let track_length = reader.read_u64::<LittleEndian>()?;
   371→        // Each track element is: image_id (u32), point2d_idx (u32) = 8 bytes
   372→        for _ in 0..track_length {
   373→            reader.read_u32::<LittleEndian>()?; // image_id
   374→            reader.read_u32::<LittleEndian>()?; // point2d_idx
   375→        }
   376→
   377→        points.push(Point3D {
   378→            id: point_id,
   379→            position: Vector3::new(x, y, z),
   380→            color: [r, g, b],
   381→            error,
   382→        });
   383→    }
   384→
   385→    Ok(points)
   386→}
   387→
   388→#[cfg(test)]
   389→mod tests {
   390→    use super::*;
   391→
   392→    #[test]
   393→    #[ignore] // Remove when implementing
   394→    fn test_load_colmap_scene() {
   395→        // TODO: Add test with fixture data
   396→        // See tests/fixtures/ directory
   397→    }
   398→}
